"use strict";(self.webpackChunklogbook=self.webpackChunklogbook||[]).push([[5315],{8181:(a,l,e)=>{e.r(l),e.d(l,{comp:()=>s,data:()=>t});var i=e(362);const n={},s=(0,e(5726).A)(n,[["render",function(a,l){const e=(0,i.g2)("RouteLink");return(0,i.uX)(),(0,i.CE)("div",null,[l[3]||(l[3]=(0,i.Fv)('<h1 id="浏览器缓存机制" tabindex="-1"><a class="header-anchor" href="#浏览器缓存机制"><span>浏览器缓存机制</span></a></h1><h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>浏览器缓存是 Web 性能优化的核心技术之一，通过将资源存储在本地，减少网络请求，提升用户体验。理解浏览器缓存机制对于前端开发、性能优化和问题排查都至关重要。</p><h2 id="缓存类型" tabindex="-1"><a class="header-anchor" href="#缓存类型"><span>缓存类型</span></a></h2><h3 id="_1-http-缓存" tabindex="-1"><a class="header-anchor" href="#_1-http-缓存"><span>1. HTTP 缓存</span></a></h3><ul><li><strong>强缓存</strong>：浏览器直接从本地缓存获取资源，不发送请求</li><li><strong>协商缓存</strong>：浏览器发送请求，服务器判断资源是否更新</li></ul><h3 id="_2-浏览器缓存" tabindex="-1"><a class="header-anchor" href="#_2-浏览器缓存"><span>2. 浏览器缓存</span></a></h3><ul><li><strong>Memory Cache</strong>：内存缓存，速度最快但容量有限</li><li><strong>Disk Cache</strong>：磁盘缓存，容量大但速度较慢</li></ul><h3 id="_3-应用缓存" tabindex="-1"><a class="header-anchor" href="#_3-应用缓存"><span>3. 应用缓存</span></a></h3><ul><li><strong>Service Worker</strong>：现代浏览器的离线缓存方案</li><li><strong>Application Cache</strong>：已废弃的 HTML5 离线缓存</li></ul><h2 id="缓存控制" tabindex="-1"><a class="header-anchor" href="#缓存控制"><span>缓存控制</span></a></h2><h3 id="http-头部字段" tabindex="-1"><a class="header-anchor" href="#http-头部字段"><span>HTTP 头部字段</span></a></h3><ul><li><code>Cache-Control</code>：现代缓存控制标准</li><li><code>Expires</code>：传统过期时间控制</li><li><code>ETag</code>：资源版本标识</li><li><code>Last-Modified</code>：最后修改时间</li></ul><h3 id="缓存策略" tabindex="-1"><a class="header-anchor" href="#缓存策略"><span>缓存策略</span></a></h3><ul><li><strong>Cache First</strong>：优先使用缓存</li><li><strong>Network First</strong>：优先使用网络</li><li><strong>Stale While Revalidate</strong>：使用缓存同时更新</li><li><strong>Network Only</strong>：仅使用网络</li><li><strong>Cache Only</strong>：仅使用缓存</li></ul><h2 id="缓存生命周期" tabindex="-1"><a class="header-anchor" href="#缓存生命周期"><span>缓存生命周期</span></a></h2><ol><li><strong>请求阶段</strong>：检查缓存是否存在且有效</li><li><strong>验证阶段</strong>：与服务器验证资源是否更新</li><li><strong>更新阶段</strong>：下载新资源并更新缓存</li><li><strong>存储阶段</strong>：将资源存储到相应缓存层</li></ol><h2 id="性能影响" tabindex="-1"><a class="header-anchor" href="#性能影响"><span>性能影响</span></a></h2><h3 id="优势" tabindex="-1"><a class="header-anchor" href="#优势"><span>优势</span></a></h3><ul><li>减少网络请求</li><li>降低服务器负载</li><li>提升页面加载速度</li><li>改善用户体验</li></ul><h3 id="挑战" tabindex="-1"><a class="header-anchor" href="#挑战"><span>挑战</span></a></h3><ul><li>缓存失效问题</li><li>版本更新困难</li><li>存储空间限制</li><li>跨域缓存问题</li></ul><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践"><span>最佳实践</span></a></h2><ol><li><strong>合理设置缓存时间</strong></li><li><strong>使用版本号或哈希值</strong></li><li><strong>区分静态资源和动态内容</strong></li><li><strong>监控缓存命中率</strong></li><li><strong>定期清理过期缓存</strong></li></ol><h2 id="相关文档" tabindex="-1"><a class="header-anchor" href="#相关文档"><span>相关文档</span></a></h2>',25)),(0,i.Lk)("ul",null,[(0,i.Lk)("li",null,[(0,i.bF)(e,{to:"/cache/cache-types.html"},{default:(0,i.k6)(()=>[...l[0]||(l[0]=[(0,i.eW)("缓存类型详解",-1)])]),_:1})]),(0,i.Lk)("li",null,[(0,i.bF)(e,{to:"/cache/cache-strategies.html"},{default:(0,i.k6)(()=>[...l[1]||(l[1]=[(0,i.eW)("缓存策略和最佳实践",-1)])]),_:1})]),(0,i.Lk)("li",null,[(0,i.bF)(e,{to:"/cache/cache-troubleshooting.html"},{default:(0,i.k6)(()=>[...l[2]||(l[2]=[(0,i.eW)("缓存问题排查和调试",-1)])]),_:1})])])])}]]),t=JSON.parse('{"path":"/cache/","title":"浏览器缓存机制","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1761186389000,"contributors":[{"name":"loopbin","username":"loopbin","email":"lzb100562@163.com","commits":1,"url":"https://github.com/loopbin"}],"changelog":[{"hash":"4638ac43c531aac6e15823223bb352dc58ce2135","time":1761186389000,"email":"lzb100562@163.com","author":"loopbin","message":"feat: 1"}]},"filePathRelative":"cache/index.md"}')}}]);